// ---------------------------------------------------------------------------
// Arbitraries
// ---------------------------------------------------------------------------

/** A valid WidgetType value. */
const widgetTypeArb: fc.Arbitrary<WidgetType> = fc.constantFrom(
  'clock', 'image', 'file', 'webpage'
);

/** A valid non-clock WidgetType value. */
const nonClockTypeArb: fc.Arbitrary<WidgetType> = fc.constantFrom(
  'image', 'file', 'webpage'
);

/** A non-empty blob URL string suitable for imageUrl. */
const blobUrlArb: fc.Arbitrary<string> = fc.string({ minLength: 1, maxLength: 60 })
  .map((s) => `blob:http://localhost/${s}`);

/**
 * A well-formed https:// URL using fc.domain() to guarantee it passes the URL
 * constructor (no spaces or special chars in the host).
 * We use fc.constantFrom with a controlled set to avoid jsdom hostname
 * normalisation edge cases.
 */
const httpsUrlArb: fc.Arbitrary<string> = fc.constantFrom(
  'https://example.com',
  'https://foo.example.com',
  'https://bar.test',
  'https://example.org',
  'https://sub.domain.io',
  'https://my-site.com',
  'https://123.example.com',
  'https://test.co.uk',
);

/** Arbitrary file text content (may be long or short). */
const fileTextArb: fc.Arbitrary<string> = fc.string({ minLength: 0, maxLength: 20_000 });

/** An arbitrary WidgetConfig. */
const widgetConfigArb: fc.Arbitrary<WidgetConfig> = fc.oneof(
  fc.constant({}),
  blobUrlArb.map((u) => ({ imageUrl: u })),
  fc.string({ minLength: 1, maxLength: 500 }).map((t) => ({ fileText: t, fileName: 'test.txt' })),
  httpsUrlArb.map((u) => ({ webpageUrl: u }))
);

/** An arbitrary positional WidgetLayout (no type/config). */
const layoutBaseArb: fc.Arbitrary<Pick<WidgetLayout, 'id' | 'x' | 'y' | 'w' | 'h'>> =
  fc.record({
    id: fc.uuid(),
    x: fc.integer({ min: 0, max: 10 }),
    y: fc.integer({ min: 0, max: 10 }),
    w: fc.integer({ min: 1, max: 4 }),
    h: fc.integer({ min: 1, max: 4 }),
  });

const noop = () => {};

