// Scenario 1: Default type when absent
// WHEN a WidgetLayout entry has no type field
// THEN the system renders that widget as a clock widget
// UC1-S2, UC2-S1, UC3-S1, UC4-S1
// ---------------------------------------------------------------------------
describe('PBT Scenario 1: Default type when absent → renders clock', () => {
  it('S1: WidgetContent with type=undefined always renders a clock widget', () => {
    fc.assert(
      fc.property(widgetConfigArb, (config) => {
        const { unmount } = render(
          <WidgetContent type={undefined} config={config} onConfigChange={noop} />
        );
        const clock = document.querySelector('[data-testid="clock-display"]');
        const result = clock !== null;
        unmount();
        return result;
      }),
      { numRuns: 20 }
    );
  });
});

