// ---------------------------------------------------------------------------
// Scenario 3: Clock shows current time on render
// WHEN a clock widget is rendered
// THEN the displayed time matches the current local time in HH:MM:SS format
// UC1-S2
// ---------------------------------------------------------------------------
describe('PBT Scenario 3: Clock shows current time on render', () => {
  beforeEach(() => { vi.useFakeTimers(); });
  afterEach(() => { vi.useRealTimers(); });

  it('S3: ClockWidget for any fixed time always shows HH:MM:SS format', () => {
    fc.assert(
      fc.property(
        // Generate an arbitrary timestamp in a reasonable range (year 2020-2030)
        fc.integer({ min: 1577836800_000, max: 1893456000_000 }),
        (ts) => {
          vi.setSystemTime(new Date(ts));
          const { unmount } = render(<ClockWidget />);
          const display = document.querySelector('[data-testid="clock-display"]');
          const text = display?.textContent ?? '';
          unmount();
          return /^\d{2}:\d{2}:\d{2}$/.test(text);
        }
      ),
      { numRuns: 30 }
    );
  });
});

// ---------------------------------------------------------------------------
// Scenario 4: Time advances each second
// WHEN one second elapses after the clock widget is rendered
// THEN the displayed time advances by one second
// UC1-S3
// ---------------------------------------------------------------------------
describe('PBT Scenario 4: Time advances each second', () => {
  beforeEach(() => { vi.useFakeTimers(); });
  afterEach(() => { vi.useRealTimers(); });

  it('S4: ClockWidget displayed text changes after 1 s for any starting time', () => {
    fc.assert(
      fc.property(
        fc.integer({ min: 1577836800_000, max: 1893456000_000 }),
        (ts) => {
          vi.setSystemTime(new Date(ts));
          const { unmount } = render(<ClockWidget />);
          const before = document.querySelector('[data-testid="clock-display"]')?.textContent;
          act(() => { vi.advanceTimersByTime(1000); });
          const after = document.querySelector('[data-testid="clock-display"]')?.textContent;
          unmount();
          return before !== after;
        }
      ),
      { numRuns: 20 }
    );
  });
});

