// ---------------------------------------------------------------------------
// Scenario 10: Previous URL revoked on replacement
// WHEN a user selects a new image to replace a previous one
// THEN the old object URL is revoked before the new one is applied
// UC2-S5 — ⚠️ PARTIAL: URL.revokeObjectURL timing is hard to property-test
// in jsdom because revocation is side-effectful and depends on React's effect
// scheduling. We implement a degenerate property using fc.constant.
// ---------------------------------------------------------------------------
describe('PBT Scenario 10 ⚠️ PARTIAL: Previous URL revoked on replacement', () => {
  it('S10: revokeObjectURL is called when imageUrl prop changes (degenerate property)', () => {
    // ⚠️ Degenerate: uses fc.constant — timing of revokeObjectURL in jsdom
    // cannot be property-tested with arbitrary inputs because React's useEffect
    // fires asynchronously after layout paints in the test environment.
    fc.assert(
      fc.property(fc.constant('blob:http://localhost/old'), (oldUrl) => {
        const revokeStub = vi.fn();
        vi.stubGlobal('URL', {
          createObjectURL: vi.fn(() => 'blob:http://localhost/new'),
          revokeObjectURL: revokeStub,
        });
        // First render with old URL
        const { rerender, unmount } = render(
          <ImageWidget config={{ imageUrl: oldUrl }} onConfigChange={noop} />
        );
        // Re-render with new URL — triggers the revoke effect
        rerender(<ImageWidget config={{ imageUrl: 'blob:http://localhost/new2' }} onConfigChange={noop} />);
        const result = revokeStub.mock.calls.length > 0;
        unmount();
        vi.unstubAllGlobals();
        return result;
      }),
      { numRuns: 3 }
    );
  });
});

