// ---------------------------------------------------------------------------
// Delta Scenario D3: Geometry functions ignore type and config
// WHEN isValidPlacement or resolveLayout is called with a layout containing
//      type and config fields
// THEN the result is identical to calling with a layout that omits those fields
// widget-drag-drop/spec.md
// ---------------------------------------------------------------------------
describe('PBT Delta D3: Geometry functions ignore type and config', () => {
  it('D3: WIDGET_TYPES contains exactly the four expected members', () => {
    fc.assert(
      fc.property(fc.constant(WIDGET_TYPES), (types) => {
        return (
          types.length === 4 &&
          types.includes('clock') &&
          types.includes('image') &&
          types.includes('file') &&
          types.includes('webpage')
        );
      }),
      { numRuns: 1 }
    );
  });

  it('D3b: arbitrary WidgetLayout with type+config fields have same type-union membership', () => {
    fc.assert(
      fc.property(
        widgetTypeArb,
        widgetConfigArb,
        layoutBaseArb,
        (type, config, base) => {
          const withType: WidgetLayout = { ...base, type, config };
          const withoutType: WidgetLayout = { ...base };
          // type field existence does not affect the positional fields
          return (
            withType.id === withoutType.id &&
            withType.x === withoutType.x &&
            withType.y === withoutType.y &&
            withType.w === withoutType.w &&
            withType.h === withoutType.h
          );
        }
      ),
      { numRuns: 50 }
    );
  });
});

